class TrieNode:
    def __init__(self):
        self.children = {}

def find_maximum_xor(nums):
    root = TrieNode()
    highest_bit = max(nums).bit_length() - 1 if nums else 0

    def insert(num):
        node = root
        for bit in range(highest_bit, -1, -1):
            b = (num >> bit) & 1
            if b not in node.children:
                node.children[b] = TrieNode()                       # extend the trie with this bit
            node = node.children[b]

    def best_xor(num):
        node = root
        result = 0
        for bit in range(highest_bit, -1, -1):
            b = (num >> bit) & 1
            opposite = 1 - b
            if opposite in node.children:
                result |= (1 << bit)                                     # a differing bit was found, take it
                node = node.children[opposite]
            else:
                node = node.children[b]
        return result

    best = 0
    for num in nums:
        insert(num)
    for num in nums:
        best = max(best, best_xor(num))
    return best


if __name__ == "__main__":
    print(find_maximum_xor([3, 10, 5, 25, 2, 8]))

